import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.factorial(n) // (math.factorial(k) * math.factorial(n - k))

print(f"m=3: {combinations(3, 3)}")
print(f"m=4: {combinations(4, 3)}")
print(f"m=5: {combinations(5, 3)}")
